fn replace_chars(s: &[char], old: char, new: char) -> Vec<char> {
    // Create a new vector to hold the result
    let mut result = Vec::with_capacity(s.len());
    
    // Iterate over each character in the input slice
    for &c in s {
        // Check if the current character is the one to be replaced
        if c == old {
            result.push(new); // Replace with new character
        } else {
            result.push(c); // Keep the original character
        }
    }
    
    result // Return the new vector
}